3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Business-day rules for an owner's effective registration date.
10	 *
11	 * <p>The registration date must fall on a business day. A Saturday or Sunday rolls forward to the
12	 * next Monday; a weekday is kept. This applies to the effective date whether supplied in the
13	 * request or defaulted to the server's current date, and every value derived from the registration
14	 * date (membership number year, the daily create-limit day) must use the adjusted date.
15	 */
16	final class RegistrationDate {
17	
18	    private RegistrationDate() {
19	    }
20	
21	    /** Roll a Saturday or Sunday forward to the next Monday; a weekday is returned unchanged. */
22	    static LocalDate toBusinessDay(LocalDate date) {
23	        DayOfWeek day = date.getDayOfWeek();
24	        if (day == DayOfWeek.SATURDAY) {
25	            return date.plusDays(2);
26	        }
27	        if (day == DayOfWeek.SUNDAY) {
28	            return date.plusDays(1);
29	        }
30	        return date;
31	    }
32	
33	    /**
34	     * The effective, business-day-adjusted registration date for a create request: the supplied
35	     * date, else the server's current date, rolled forward off any weekend.
36	     */
37	    static LocalDate effective(OwnerFieldsDto request) {
38	        LocalDate supplied = request.getRegistrationDate();
39	        return toBusinessDay(supplied != null ? supplied : LocalDate.now());
40	    }
41	}
